import{_ as a,o as s,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/getting-started.md","filePath":"es-ES/user-guide/getting-started.md","lastUpdated":1785993908000}'),n={name:"es-ES/user-guide/getting-started.md"};function i(t,e,d,l,c,u){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><p>Consigue la última versión desde el <a href="./../">botón de descarga</a> de la página de inicio — se publican dos variantes en cada versión:</p><ul><li><strong>Instalador</strong> (<code>Lertaro-Setup.exe</code>) — recomendado. Registra el servicio de indexación en segundo plano y puede iniciar Lertaro junto con Windows.</li><li><strong>Portable</strong> (<code>Lertaro-Portable.zip</code>) — descomprímelo y ejecútalo, sin instalación. Aun así, puedes instalar más adelante el servicio en segundo plano desde <strong>Configuración → Estado del Servicio</strong>. Si tu equipo todavía no tiene el .NET Desktop Runtime que necesita Lertaro, ejecuta una vez el <code>install-dotnet-runtime.bat</code> incluido — el instalador gestiona este paso automáticamente, pero la versión portable no puede. Cuando termines con una instalación portable, no hay ningún desinstalador que limpie después de ti: haz doble clic en el <code>portable-cleanup-registry.reg</code> incluido (confirma el aviso) antes de borrar la carpeta, para eliminar las dos entradas del registro por usuario que Lertaro crea por sí mismo — el registro del protocolo URI <code>lertaro://</code> y su entrada de &quot;iniciar con Windows&quot;. Ambas son solo por usuario (HKCU), así que no hace falta ningún aviso de administrador.</li></ul><p>Cada una de ellas se publica para <strong>x64</strong> y para <strong>ARM64</strong>. Los nombres de arriba son las versiones x64, que funcionan en cualquier PC reciente — incluido Windows on ARM, donde se ejecutan emuladas. En un equipo ARM es preferible <code>Lertaro-Setup-arm64.exe</code> o <code>Lertaro-Portable-arm64.zip</code>, que son nativas. Las actualizaciones automáticas mantienen la arquitectura que instalaste, así que pasar de una a otra implica descargar la otra versión tú mismo.</p><p>En el primer arranque, Lertaro instala e inicia un servicio de Windows (<code>Lertaro.Service</code>) que se encarga de la indexación de archivos. Esta división existe a propósito — ver <a href="./../dev-guide/architecture.html">Arquitectura</a> si tienes curiosidad por saber por qué — pero, como usuario, lo único que necesitas saber es: <strong>Configuración → Estado del Servicio</strong> te dice si el servicio está instalado y en ejecución, y te permite instalarlo si no lo está.</p><h2 id="las-tres-ventanas" tabindex="-1">Las tres ventanas <a class="header-anchor" href="#las-tres-ventanas" aria-label="Permalink to &quot;Las tres ventanas&quot;">​</a></h2><p>Lertaro no tiene una sola ventana de búsqueda — se adapta a cómo la estés usando:</p><ul><li><strong>Ventana principal</strong> — la ventana completa que obtienes desde la barra de tareas o el acceso directo del menú Inicio, con la lista de resultados más grande y un panel de Acciones dentro de la propia ventana.</li><li><strong>Ventana rápida</strong> — la ventana emergente compacta, siempre visible, que invocas con el atajo global de mostrar/ocultar (doble pulsación de <code>Ctrl</code> por defecto). Pensada para la memoria muscular de &quot;pulsar atajo → escribir → Intro&quot;.</li><li><strong>Ventana en línea</strong> — incrusta una barra de búsqueda de Lertaro directamente en un diálogo de archivos nativo compatible o en una ventana del Explorador de archivos, de modo que puedas buscar sin salir del diálogo en el que ya estás.</li></ul><p>Las tres comparten el mismo motor de búsqueda, el mismo sistema de atajos y el mismo menú de Acciones — la diferencia está puramente en dónde y cómo aparecen.</p><h2 id="busqueda-basica" tabindex="-1">Búsqueda básica <a class="header-anchor" href="#busqueda-basica" aria-label="Permalink to &quot;Búsqueda básica&quot;">​</a></h2><p>Los archivos recientes, los favoritos y el historial están al alcance sin escribir nada — son pestañas del <a href="./settings/quick-panel.html">Panel Rápido</a>, que se abre sobre la ventana que tengas delante en lugar de dentro de la ventana de búsqueda.</p><p>Simplemente empieza a escribir. Los resultados se actualizan a medida que escribes, ordenados por relevancia (ver <a href="./search-syntax.html">Sintaxis de búsqueda</a> para saber cómo funcionan la coincidencia y la clasificación). Usa los <a href="./hotkeys.html">atajos configurables de elemento siguiente/anterior</a> (teclas de flecha por defecto) para mover la selección, e Intro para abrir el resultado resaltado.</p><p>A continuación: <a href="./search-syntax.html">Sintaxis de búsqueda</a> para sacarle el máximo partido al cuadro de consulta.</p>',14)])])}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
